{"rule_id": "R8", "title": "nova_telecom has refund_allowed=false but refund on a captured payment succeeds", "test_code": "import os
import uuid
import httpx

BASE = os.environ["PAYMENT_API_URL"]


def api(method, path, merchant_id=None, body=None, idem=None):
    headers = {}
    if merchant_id is not None:
        headers["X-Merchant-Id"] = merchant_id
    if idem is not None:
        headers["Idempotency-Key"] = idem
    return httpx.request(method, BASE + path, json=body, headers=headers)


def test_nova_refund_not_allowed_on_captured_payment():
    key = str(uuid.uuid4())
    body = {
        "amount": 10000,
        "currency": "USD",
        "payment_method": "card",
        "payer_ref": "payer-" + uuid.uuid4().hex[:10],
    }

    r = api("POST", "/v1/payments", "nova_telecom", body, key)
    assert r.status_code == 201, r.text
    payment_id = r.json()["id"]

    r = api("POST", f"/v1/payments/{payment_id}/capture", "nova_telecom")
    assert r.status_code == 200, r.text

    r = api("POST", f"/v1/payments/{payment_id}/refunds", "nova_telecom", {"amount": 100})
    assert r.status_code == 403, r.text
    assert r.json()["error"]["code"] == "refund_not_allowed", r.text
"}

{"rule_id": "R7", "title": "Capture amount 0 or negative returns invalid_request instead of capture_exceeds_authorized", "test_code": "import os
import uuid
import httpx

BASE = os.environ["PAYMENT_API_URL"]


def api(method, path, merchant_id=None, body=None, idem=None):
    headers = {}
    if merchant_id is not None:
        headers["X-Merchant-Id"] = merchant_id
    if idem is not None:
        headers["Idempotency-Key"] = idem
    return httpx.request(method, BASE + path, json=body, headers=headers)


def test_capture_zero_or_negative_is_capture_exceeds_authorized():
    for amount in (0, -1):
        key = str(uuid.uuid4())
        body = {
            "amount": 10000,
            "currency": "USD",
            "payment_method": "card",
            "payer_ref": "payer-" + uuid.uuid4().hex[:10],
        }

        r = api("POST", "/v1/payments", "nova_telecom", body, key)
        assert r.status_code == 201, r.text
        payment_id = r.json()["id"]

        r = api("POST", f"/v1/payments/{payment_id}/capture", "nova_telecom", {"amount": amount})
        assert r.status_code == 422, r.text
        assert r.json()["error"]["code"] == "capture_exceeds_authorized", r.text
"}

